package studio.jiayu.neoagent;
public final class FloatingChatGeometryTest {
 static int checks;static void yes(boolean condition){checks++;if(!condition)throw new AssertionError("floating geometry "+checks);}
 public static void main(String[] args){int[] p=FloatingChatGeometry.position(1080,2400,144,144,24,1,.5f);yes(p[0]==912);yes(p[1]==1128);float[] n=FloatingChatGeometry.normalize(1080,2400,144,144,24,p[0],p[1]);yes(n[0]==1);yes(n[1]==.5f);int[] moved=FloatingChatGeometry.avoid(1080,2400,144,144,24,p[0],p[1],900,1100,1080,1400);yes(moved!=null);yes(moved[1]+144<=1100||moved[1]>=1400);yes(FloatingChatGeometry.avoid(1080,2400,144,144,24,p[0],p[1],0,0,1080,2400)==null);int[] stable=FloatingChatGeometry.avoid(1080,2400,144,144,24,p[0],p[1],0,0,100,100);yes(stable[0]==p[0]&&stable[1]==p[1]);int[] clamped=FloatingChatGeometry.position(300,600,100,100,10,-100,100);yes(clamped[0]==10&&clamped[1]==490);int[] bad=FloatingChatGeometry.position(300,600,100,100,10,Float.NaN,Float.POSITIVE_INFINITY);yes(bad[0]==190&&bad[1]==250);int[] small=FloatingChatGeometry.position(80,100,80,80,30,1,.5f);yes(small[0]==0&&small[1]==10);for(int x=0;x<=10;x++)for(int y=0;y<=10;y++){int[] at=FloatingChatGeometry.position(500,900,48,48,12,x/10f,y/10f);yes(at[0]>=12&&at[0]+48<=488&&at[1]>=12&&at[1]+48<=888);float[] unit=FloatingChatGeometry.normalize(500,900,48,48,12,at[0],at[1]);yes(Math.abs(unit[0]-x/10f)<.003&&Math.abs(unit[1]-y/10f)<.003);}System.out.println("FloatingChatGeometryTest: "+checks+" checks passed");}
}
